import json
from packet_routing_sim.core import (
    converge_topology,
    replay_dv_scenario,
    compute_topology,
)

CHAIN3 = {
    "nodes": ["A", "B", "C"],
    "links": [
        {"from": "A", "to": "B", "metric": 5},
        {"from": "B", "to": "C", "metric": 7},
    ],
}
DV_CHAIN = {
    "nodes": ["A", "B", "C"],
    "links": [
        {"from": "A", "to": "B", "metric": 1},
        {"from": "B", "to": "C", "metric": 1},
    ],
}
DIAMOND = {
    "nodes": ["A", "B", "C", "D"],
    "links": [
        {"from": "A", "to": "B", "metric": 1},
        {"from": "A", "to": "C", "metric": 1},
        {"from": "B", "to": "D", "metric": 1},
        {"from": "C", "to": "D", "metric": 1},
    ],
}

c = converge_topology(CHAIN3)
assert c["convergenceRound"] == 1
assert c["rounds"][-1]["routers"] == compute_topology(CHAIN3)["routers"]

r = replay_dv_scenario(
    DV_CHAIN,
    {"infinityMetric": 8,
     "events": [{"time": 1, "action": "node-down", "node": "C"}]},
)
entry = r["timeline"][1]
assert entry["convergenceRound"] == 6, entry["convergenceRound"]
metrics = [
    (s["routers"]["A"]["C"]["metric"], s["routers"]["B"]["C"]["metric"])
    for s in entry["rounds"]
]
assert metrics == [
    (2, None), (None, 3), (4, None), (None, 5),
    (6, None), (None, 7), (None, None),
], metrics

r2 = replay_dv_scenario(
    DV_CHAIN,
    {"infinityMetric": 8, "holdDownRounds": 2,
     "events": [{"time": 1, "action": "node-down", "node": "C"}]},
)
e2 = r2["timeline"][1]
assert e2["convergenceRound"] == 2
assert e2["rounds"][0]["holdDowns"]["A"] == {"C": 2}
assert e2["rounds"][1]["holdDowns"]["A"] == {"C": 1}
assert e2["rounds"][2]["holdDowns"]["A"] == {}

r3 = replay_dv_scenario(
    DIAMOND,
    {"infinityMetric": 8, "holdDownRounds": 2,
     "events": [{"time": 1, "action": "link-down", "from": "A", "to": "B"}]},
)
e3 = r3["timeline"][1]
assert e3["convergenceRound"] == 4
assert e3["rounds"][3]["routers"]["A"]["D"] == {"nextHop": "C", "metric": 2}

ev = [{"time": 1, "action": "node-down", "node": "C"}]
a = replay_dv_scenario(DV_CHAIN, {"infinityMetric": 8, "events": ev})
b = replay_dv_scenario(
    DV_CHAIN, {"infinityMetric": 8, "holdDownRounds": 0, "events": ev}
)
assert json.dumps(a, sort_keys=True) == json.dumps(b, sort_keys=True)
print("sanity OK")

