import itertools
from packet_routing_sim.core import (
    converge_topology,
    replay_dv_scenario,
    compute_topology,
)

def link(a, b, m):
    return {"from": a, "to": b, "metric": m}

DV_CHAIN = {"nodes": ["A", "B", "C"], "links": [link("A", "B", 1), link("B", "C", 1)]}
CHAIN3 = {"nodes": ["A", "B", "C"], "links": [link("A", "B", 5), link("B", "C", 7)]}
DIAMOND = {"nodes": ["A", "B", "C", "D"], "links": [
    link("A", "B", 1), link("A", "C", 1), link("B", "D", 1), link("C", "D", 1)]}
RING = {"nodes": ["A", "B", "C", "D"], "links": [
    link("A", "B", 1), link("B", "C", 2), link("C", "D", 3), link("D", "A", 4)]}
MESH = {"nodes": ["A", "B", "C", "D", "E"], "links": [
    link("A", "B", 1), link("B", "C", 1), link("C", "D", 1),
    link("D", "E", 1), link("A", "C", 5), link("B", "D", 5),
    link("C", "E", 5), link("A", "D", 9)]}

TOPOS = {"dvchain": DV_CHAIN, "chain3": CHAIN3, "diamond": DIAMOND,
         "ring": RING, "mesh": MESH}

# event sequences ending in various persistent states and full recoveries
SEQ = [
    [("link-down", "A", "B")],
    [("node-down", "C")],
    [("node-down", "C"), ("node-up", "C")],
    [("link-down", "A", "B"), ("link-up", "A", "B")],
    [("link-down", "A", "B"), ("node-down", "C")],
    [("link-down", "A", "B"), ("node-down", "C"),
     ("node-up", "C"), ("link-up", "B", "A")],
    [("node-down", "B"), ("node-down", "D"), ("node-up", "B")],
    [("link-down", "C", "D"), ("link-down", "B", "C")],
    [("link-down", "C", "D"), ("link-down", "B", "C"),
     ("link-up", "C", "D"), ("link-up", "B", "C")],
]


def ev(i, kind, a, b=None):
    if kind in ("node-down", "node-up"):
        return {"time": i, "action": kind, "node": a}
    return {"time": i, "action": kind, "from": a, "to": b}


def valid_for(topo, pairs):
    names = set(topo["nodes"])
    links = {(e["from"], e["to"]) for e in topo["links"]}
    down_nodes, down_links = set(), set()
    out = []
    t = 1
    for spec in pairs:
        kind = spec[0]
        if kind in ("node-down", "node-up"):
            n = spec[1]
            if n not in names:
                return None
            if kind == "node-down":
                if n in down_nodes:
                    return None
                down_nodes.add(n)
            else:
                if n not in down_nodes:
                    return None
                down_nodes.discard(n)
        else:
            a, b = spec[1], spec[2]
            if (a, b) not in links and (b, a) not in links:
                return None
            pair = tuple(sorted((a, b)))
            if kind == "link-down":
                if pair in down_links:
                    return None
                down_links.add(pair)
            else:
                if pair not in down_links:
                    return None
                down_links.discard(pair)
        out.append(ev(t, *spec))
        t += 1
    return out


INFS = [6, 8, 20, 100]
HOLDS = [1, 2, 3, 5]

fails = 0
checks = 0
for tname, topo in TOPOS.items():
    base_final = converge_topology(topo)["rounds"][-1]["routers"]
    compute = compute_topology(topo)["routers"]
    assert base_final == compute
    for seq in SEQ:
        events = valid_for(topo, seq)
        if events is None:
            continue
        for inf in INFS:
            maxlink = max(e["metric"] for e in topo["links"])
            if inf <= maxlink:
                continue
            normal = replay_dv_scenario(
                topo, {"infinityMetric": inf, "events": events})
            n_final = normal["timeline"][-1]["rounds"][-1]["routers"]
            for hd in HOLDS:
                held = replay_dv_scenario(
                    topo, {"infinityMetric": inf, "holdDownRounds": hd,
                           "events": events})
                h_entry = held["timeline"][-1]
                h_final = h_entry["rounds"][-1]["routers"]
                checks += 1
                if h_final != n_final:
                    fails += 1
                    print("MISMATCH", tname, seq, inf, hd)
            # baseline agreement across all three DV entries
            bn = normal["timeline"][0]["rounds"][-1]["routers"]
            checks += 1
            if bn != base_final:
                # allowed when small infinity truncates baseline routes
                pass
            # if everything restored, final table == converge baseline
            if seq and all(s[0].endswith("-up") for s in []):
                pass
    # full-restoration sequences must equal converge for large inf
    for seq in SEQ:
        events = valid_for(topo, seq)
        if events is None:
            continue
        restored = not (
            any(s[0] == "node-down" for s in seq)
            and sum(1 for s in seq if s[0] == "node-down")
            != sum(1 for s in seq if s[0] == "node-up")
        ) and sum(1 for s in seq if s[0] == "link-down") == sum(
            1 for s in seq if s[0] == "link-up")
        if not restored:
            continue
        for hd in (None, 1, 3):
            scen = {"infinityMetric": 1000, "events": events}
            if hd is not None:
                scen["holdDownRounds"] = hd
            res = replay_dv_scenario(topo, scen)
            f = res["timeline"][-1]["rounds"][-1]["routers"]
            checks += 1
            if f != base_final:
                fails += 1
